export default {
	previewFile() {
		let baseUrl = "http://192.168.1.14:8000/";  // Your backend URL
		let selectedFile = task_attachments_table.selectedRow; // Get selected file details

		if (!selectedFile) {
			showAlert("No file selected!", "warning");
			return;
		}

		let fileUrl = baseUrl + selectedFile.filePath;
		let fileType = selectedFile.fileType.toLowerCase(); // Normalize file type

		// 🛑 Reset stored values before updating
		storeValue("fileURL", ""); // Ensures the previous file isn't shown
		storeValue("fileType", "");

		// ✅ Store the new file details
		storeValue("fileURL", fileUrl);
		storeValue("fileType", fileType);

		// 🛠 Debugging to ensure correct values
		console.log("Stored File URL:", fileUrl);
		console.log("Stored File Type:", fileType);

		// Wait for stored values to update, then trigger modal
		setTimeout(() => {
			this.handleFilePreview(fileType, fileUrl);
		}, 200);
	},

	handleFilePreview(fileType, fileUrl) {
		// 📸 Ensure all image types work
		if (fileType.startsWith("image/")) {
			showModal(image_preview.name);

		} else if (fileType === "application/pdf" || fileType === "text/plain" || fileType === "application/json") {
			showModal(pdf_doccument_preview.name);

		} else {
			showAlert("File type not supported for preview!", "warning");
		}
	}
};

